#' Two-Stage Crossover ANOVA
#'
#' 
#' @param data .
#' @param x .
#' @param k .
#' @param a .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$anova} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$h0} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$anova$asDF}
#'
#' \code{as.data.frame(results$anova)}
#'
#' @export
TwoStageCrossoverANOVA <- function(
    data,
    x,
    k,
    a = "0.05") {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("TwoStageCrossoverANOVA requires jmvcore to be installed (restart may be required)")

    if ( ! missing(x)) x <- jmvcore::resolveQuo(jmvcore::enquo(x))
    if ( ! missing(k)) k <- jmvcore::resolveQuo(jmvcore::enquo(k))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(x), x, NULL),
            `if`( ! missing(k), k, NULL))

    for (v in k) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- TwoStageCrossoverANOVAOptions$new(
        x = x,
        k = k,
        a = a)

    analysis <- TwoStageCrossoverANOVAClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

